import{_ as e,c as i,o as l,ah as r}from"./chunks/framework.EWc8u_kM.js";const m=JSON.parse('{"title":"PetLoss — 隱私政策","description":"PetLoss 隱私政策：一款私密、離線的寵物紀念與哀傷支持 App。","frontmatter":{"title":"PetLoss — 隱私政策","description":"PetLoss 隱私政策：一款私密、離線的寵物紀念與哀傷支持 App。"},"headers":[],"relativePath":"privacy/index.md","filePath":"privacy/index.md"}'),t={name:"privacy/index.md"};function h(o,a,s,n,d,p){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="petloss-—-隱私政策" tabindex="-1">PetLoss — 隱私政策 <a class="header-anchor" href="#petloss-—-隱私政策" aria-label="Permalink to “PetLoss — 隱私政策”">​</a></h1><p>最後更新：2025-01-18</p><p>PetLoss 是一款為寵物離世提供紀念與陪伴的私密離線應用。本政策說明應用如何處理資料及其用途。</p><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to “概要”">​</a></h2><ul><li>無帳號、無登入。</li><li>無廣告、無統計 SDK、無第三方追蹤。</li><li>你的紀念專案與日記僅保存在裝置本地。</li><li>僅在你選擇匯入或儲存時存取照片。</li><li>網路僅用於 App Store 購買/恢復，或你開啟外部連結/寄送郵件時使用。</li></ul><h2 id="我們在裝置本地保存的資料" tabindex="-1">我們在裝置本地保存的資料 <a class="header-anchor" href="#我們在裝置本地保存的資料" aria-label="Permalink to “我們在裝置本地保存的資料”">​</a></h2><p>為提供核心功能，我們會在本地保存：</p><ul><li>紀念專案（寵物名、日期、備註）、模板與設定。</li><li>匯入的照片與你產生的匯出內容。</li><li>日記與引導記錄。</li><li>購買狀態（Pro 權限）本地快取。</li><li>提醒通知偏好（如你開啟）。</li></ul><p>你可以在應用內刪除專案，或透過移除應用清除全部資料。</p><h2 id="照片與檔案" tabindex="-1">照片與檔案 <a class="header-anchor" href="#照片與檔案" aria-label="Permalink to “照片與檔案”">​</a></h2><p>PetLoss 僅在你選擇匯入或儲存媒體時請求照片權限。所選照片會拷貝到應用沙盒中以離線使用。備份與匯出只會在你選擇位置時保存到檔案。</p><h2 id="應用內購買" tabindex="-1">應用內購買 <a class="header-anchor" href="#應用內購買" aria-label="Permalink to “應用內購買”">​</a></h2><p>購買由 Apple 透過 StoreKit 處理，我們不會收到你的支付資訊。Apple 可能會依其政策處理購買記錄。</p><h2 id="我們不收集的內容" tabindex="-1">我們不收集的內容 <a class="header-anchor" href="#我們不收集的內容" aria-label="Permalink to “我們不收集的內容”">​</a></h2><ul><li>不收集個人識別資訊（姓名、電子郵件、電話、精確位置）。</li><li>不存取通訊錄、相機、麥克風或行事曆。</li><li>不使用廣告識別碼或行為追蹤。</li></ul><h2 id="可選的郵件支援" tabindex="-1">可選的郵件支援 <a class="header-anchor" href="#可選的郵件支援" aria-label="Permalink to “可選的郵件支援”">​</a></h2><p>如需支援，請寄信至 <a href="mailto:lidonghui11911@gmail.com" target="_blank" rel="noreferrer">lidonghui11911@gmail.com</a>。郵件由你的郵件應用送出，你可自行決定分享內容。</p><h2 id="兒童隱私" tabindex="-1">兒童隱私 <a class="header-anchor" href="#兒童隱私" aria-label="Permalink to “兒童隱私”">​</a></h2><p>應用分級為 4+。我們不會主動收集兒童的個人資訊。</p><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to “安全”">​</a></h2><p>你的資料存放在 iOS 沙盒中。請保持系統更新並保護好裝置。</p><h2 id="政策更新" tabindex="-1">政策更新 <a class="header-anchor" href="#政策更新" aria-label="Permalink to “政策更新”">​</a></h2><p>我們可能會更新本政策，並在本頁頂部更新日期。</p><h2 id="聯絡" tabindex="-1">聯絡 <a class="header-anchor" href="#聯絡" aria-label="Permalink to “聯絡”">​</a></h2><p>如對隱私或本應用有任何疑問，請寄信至：lidonghui11911@gmail.com</p>',25)])])}const P=e(t,[["render",h]]);export{m as __pageData,P as default};
